        "American": "North America", "Indonesian": "Asia", "Belgian": "Europe", 
        "Canadian": "North America", "Italian": "Europe"
    }

    clusters = {}
    for row in table:
        continent = nationality_to_continent[row["nationality"]]
        if continent not in clusters:
            clusters[continent] = []
        clusters[continent].append(row["index"])

    # Assigning cluster labels and names
    cluster_labels = {}
    label = 0
    for continent, indices in clusters.items():
        for index in indices:
            cluster_labels[index] = {"cluster_name": continent, "cluster_label": str(label)}
